.ds-container {
    padding: 28px 32px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}

.ds-container h1, .ds-container h2, .ds-container h3 { color: #1a2744; letter-spacing: 0.01em; }

.ds-header {
    background: linear-gradient(135deg, #0f1e3d 0%, #1a2744 55%, #273b66 100%);
    color: #e9eef7;
    border-radius: 6px;
    padding: 28px 32px;
    margin-bottom: 24px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-left: 6px solid #c9a14a;
    box-shadow: 0 4px 18px rgba(15,30,61,0.18);
}
.ds-header-badge {
    display: inline-block;
    background: rgba(201,161,74,0.18);
    color: #f2d58a;
    border: 1px solid rgba(201,161,74,0.45);
    padding: 4px 12px;
    font-size: 0.72rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    border-radius: 3px;
    margin-bottom: 10px;
}
.ds-header h1 {
    color: #ffffff;
    font-size: 1.7rem;
    font-weight: 700;
    margin: 0 0 6px 0;
}
.ds-header-subtitle {
    color: #b8c2d6;
    font-size: 0.9rem;
    margin: 0;
}
.ds-header-period {
    text-align: right;
    padding: 14px 20px;
    background: rgba(201,161,74,0.1);
    border: 1px solid rgba(201,161,74,0.35);
    border-radius: 4px;
    min-width: 140px;
}
.ds-header-period-label {
    color: #f2d58a;
    font-size: 0.7rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin-bottom: 4px;
}
.ds-header-period-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #ffffff;
}
.ds-header-period-of {
    color: #b8c2d6;
    font-size: 1rem;
    margin: 0 4px;
    font-weight: 400;
}

.ds-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.ds-kpi-card {
    background: #ffffff;
    border: 1px solid #dfe3ea;
    border-radius: 4px;
    padding: 20px;
    position: relative;
    transition: box-shadow 0.2s ease, transform 0.2s ease;
}
.ds-kpi-card:hover { box-shadow: 0 6px 18px rgba(26,39,68,0.08); transform: translateY(-2px); }
.ds-kpi-icon {
    position: absolute;
    top: 16px;
    right: 16px;
    width: 32px;
    height: 32px;
    border-radius: 3px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 0.85rem;
    letter-spacing: 0.05em;
}
.ds-kpi-budget .ds-kpi-icon { background: #eef3fb; color: #2c4a7a; }
.ds-kpi-compliance .ds-kpi-icon { background: #e7f3ec; color: #2f7a4b; }
.ds-kpi-trust .ds-kpi-icon { background: #e8f0f8; color: #2a5a8e; }
.ds-kpi-culture .ds-kpi-icon { background: #f3ecf7; color: #6a3e8e; }
.ds-kpi-risk .ds-kpi-icon { background: #fbeeea; color: #a04023; }

.ds-kpi-label {
    color: #5b6b85;
    font-size: 0.72rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    margin-bottom: 10px;
    font-weight: 600;
}
.ds-kpi-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #1a2744;
    margin-bottom: 8px;
    line-height: 1.1;
}
.ds-kpi-sub { color: #8492a9; font-size: 0.75rem; }
.ds-kpi-bar {
    height: 6px;
    background: #edf0f5;
    border-radius: 3px;
    overflow: hidden;
    margin-top: 6px;
}
.ds-kpi-bar-fill {
    height: 100%;
    background: linear-gradient(90deg, #2c4a7a, #3d6da8);
    width: 50%;
    transition: width 0.35s ease;
}
.ds-kpi-compliance .ds-kpi-bar-fill { background: linear-gradient(90deg, #2f7a4b, #52b788); }
.ds-kpi-trust .ds-kpi-bar-fill { background: linear-gradient(90deg, #2a5a8e, #4d8bc8); }
.ds-kpi-culture .ds-kpi-bar-fill { background: linear-gradient(90deg, #6a3e8e, #a074c5); }
.ds-kpi-bar-risk { background: linear-gradient(90deg, #a04023, #d4702a) !important; }

.ds-briefing {
    background: #ffffff;
    border: 1px solid #dfe3ea;
    border-left: 4px solid #c9a14a;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.ds-briefing-meta { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
.ds-briefing-tag {
    background: #fdf7e8;
    color: #8a6a1f;
    border: 1px solid #e6d59a;
    padding: 3px 10px;
    font-size: 0.7rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    border-radius: 3px;
    font-weight: 600;
}
.ds-briefing-timeline {
    color: #5b6b85;
    font-size: 0.82rem;
    font-weight: 500;
}
.ds-briefing-title {
    font-size: 1.35rem;
    margin: 4px 0 12px 0;
    color: #0f1e3d;
    font-weight: 700;
}
.ds-briefing-body { color: #3a4a68; line-height: 1.6; font-size: 0.95rem; }
.ds-briefing-body strong { color: #0f1e3d; }

.ds-controls {
    background: #ffffff;
    border: 1px solid #dfe3ea;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.ds-controls-heading h3 {
    margin: 0 0 4px 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #0f1e3d;
}
.ds-controls-sub { color: #6b7a95; font-size: 0.85rem; margin-bottom: 20px; }
.ds-decisions-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 18px;
    margin-bottom: 20px;
}
.ds-decision { display: flex; flex-direction: column; }
.ds-decision label {
    font-size: 0.8rem;
    font-weight: 600;
    color: #1a2744;
    margin-bottom: 6px;
    letter-spacing: 0.02em;
}
.ds-decision select {
    background: #ffffff;
    border: 1px solid #c4cbd8;
    color: #1a2744;
    border-radius: 4px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.9rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.ds-decision select:focus {
    outline: none;
    border-color: #c9a14a;
    box-shadow: 0 0 0 3px rgba(201,161,74,0.18);
}
.ds-decision select option { background: #ffffff; color: #1a2744; }
.ds-decision-hint {
    color: #6b7a95;
    font-size: 0.78rem;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
    min-height: 18px;
}

.ds-actions { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
.ds-submit-btn {
    background: linear-gradient(135deg, #1a2744, #2c4a7a);
    color: #ffffff;
    border: none;
    border-radius: 4px;
    padding: 11px 28px;
    font-weight: 600;
    font-size: 0.92rem;
    letter-spacing: 0.03em;
    transition: all 0.2s ease;
}
.ds-submit-btn:hover {
    background: linear-gradient(135deg, #0f1e3d, #1a3558);
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(15,30,61,0.25);
    color: #ffffff;
}
.ds-undo-btn {
    border: 1px solid #c4cbd8;
    color: #5b6b85;
    background: #ffffff;
    border-radius: 4px;
    padding: 8px 16px;
    font-size: 0.85rem;
}
.ds-undo-btn:hover { background: #f4f5f7; color: #1a2744; }

.ds-event-log {
    background: #0f1e3d;
    color: #e9eef7;
    border-radius: 4px;
    padding: 22px 26px;
    margin-bottom: 24px;
    border-left: 4px solid #c9a14a;
}
.ds-event-log h3 {
    color: #f2d58a;
    font-size: 0.78rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin: 0 0 12px 0;
    font-weight: 600;
}
.ds-event-log-body {
    color: #c7d0e2;
    font-size: 0.88rem;
    line-height: 1.7;
    max-height: 220px;
    overflow-y: auto;
}
.ds-event-log-body .ds-log-entry { padding: 6px 0; border-bottom: 1px dashed rgba(201,161,74,0.18); }
.ds-event-log-body .ds-log-entry:last-child { border-bottom: none; }
.ds-event-log-body .ds-log-positive { color: #7fd4a1; }
.ds-event-log-body .ds-log-negative { color: #e89a7a; }
.ds-event-log-body .ds-log-neutral { color: #c7d0e2; }

.ds-charts-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
    gap: 18px;
    margin-bottom: 24px;
}
.ds-chart-card {
    background: #ffffff;
    border: 1px solid #dfe3ea;
    border-radius: 4px;
    padding: 20px;
    height: 320px;
}

.ds-history {
    background: #ffffff;
    border: 1px solid #dfe3ea;
    border-radius: 4px;
    padding: 22px 26px;
}
.ds-history h3 {
    font-size: 0.95rem;
    margin: 0 0 14px 0;
    color: #0f1e3d;
    font-weight: 700;
}
.ds-history table { margin: 0; font-size: 0.85rem; }
.ds-history table thead th {
    background: #f4f5f7;
    color: #1a2744;
    border-bottom: 2px solid #c9a14a;
    font-weight: 600;
    font-size: 0.78rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    padding: 10px 12px;
}
.ds-history table tbody td {
    padding: 10px 12px;
    border-bottom: 1px solid #edf0f5;
    color: #3a4a68;
}

@media (max-width: 768px) {
    .ds-container { padding: 16px; }
    .ds-header { flex-direction: column; align-items: flex-start; gap: 16px; padding: 20px; }
    .ds-header-period { text-align: left; width: 100%; }
    .ds-kpi-grid { grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 12px; }
    .ds-kpi-value { font-size: 1.5rem; }
    .ds-decisions-grid { grid-template-columns: 1fr; }
    .ds-charts-grid { grid-template-columns: 1fr; }
}

