        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 5000000,
                    complianceScore: 50,
                    customerTrust: 70,
                    privacyCulture: 30,
                    regulatoryRisk: 60,
                    totalFines: 0,
                    complianceHistory: [],
                    trustHistory: [],
                    cultureHistory: [],
                    riskHistory: [],
                    budgetHistory: [],
                    eventLog: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    choice1: '',
                    choice2: '',
                    choice3: '',
                    choice4: ''
                };
            }
            var self = this;
            setTimeout(function() { self._updateBriefing(state); }, 100);
        }

        _updateBriefing(state) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            if (!round) return;

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.textContent = t(round.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.briefKey);

            var timelineEl = document.getElementById('briefingTimeline');
            if (timelineEl) timelineEl.textContent = t(round.timelineKey);

            for (var i = 0; i < round.choices.length; i++) {
                var c = round.choices[i];
                var labelEl = document.getElementById('choice' + (i+1) + 'Label');
                var selEl = document.getElementById('choice' + (i+1) + 'Select');
                var hintEl = document.getElementById('choice' + (i+1) + 'Hint');
                if (labelEl) labelEl.textContent = t(c.labelKey);
                if (hintEl) hintEl.textContent = t(c.hintKey);
                if (selEl) {
                    selEl.innerHTML = '';
                    for (var j = 0; j < c.options.length; j++) {
                        var opt = document.createElement('option');
                        opt.value = c.options[j].value;
                        opt.textContent = t(c.options[j].textKey);
                        selEl.appendChild(opt);
                    }
                    var wrapper = selEl.parentElement;
                    if (wrapper) wrapper.style.display = '';
                }
            }
            for (var k = round.choices.length; k < 4; k++) {
                var hideSel = document.getElementById('choice' + (k+1) + 'Select');
                if (hideSel && hideSel.parentElement) hideSel.parentElement.style.display = 'none';
            }
        }

        validateDecisions(decisions) {
            // v1.1.0 FIX: do NOT call _updateBriefing() here. It rebuilt every <select>'s
            // options (innerHTML=''), which resets selectedIndex to 0 and silently discarded
            // the player's real choices — every round was scored as option[0]. The current
            // round's selects are already rendered; we only need to read them.
            var period = window.mySimulation.state.currentPeriod || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            for (var i = 0; i < round.choices.length; i++) {
                var selEl = document.getElementById('choice' + (i+1) + 'Select');
                if (!selEl || !selEl.value) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('choice_warning'), 'warning'
                    );
                    return false;
                }
                decisions['choice' + (i+1)] = selEl.value;
                decisions['impact' + (i+1)] = round.choices[i].impactKey;
            }
            return true;
        }

        calculateResults(state) {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var period = state.currentPeriod;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var d = state.decisions;

            var totalCost = 0;
            var dCompliance = 0, dTrust = 0, dCulture = 0, dRisk = 0;
            var fineMult = 1;
            var logEntries = [];

            for (var i = 0; i < round.choices.length; i++) {
                var c = round.choices[i];
                var choiceVal = d['choice' + (i+1)];
                var impact = this.IMPACTS[c.impactKey][choiceVal];
                if (!impact) continue;
                totalCost += Math.abs(impact.cost);
                dCompliance += impact.compliance;
                dTrust += impact.trust;
                dCulture += impact.culture;
                dRisk += impact.risk;
                if (impact.fineMult !== undefined) fineMult = impact.fineMult;
            }

            // Round-specific events and regulatory fines
            var fine = 0;
            var eventText = '';

            if (period === 3) {
                // Breach round — compute regulatory fine
                var baseFine = 1200000;
                var riskMod = 1 + (state.domainState.regulatoryRisk - 50) / 100;
                var complianceMod = 1 - (state.domainState.complianceScore - 50) / 200;
                fine = Math.round(baseFine * fineMult * Math.max(0.3, riskMod) * Math.max(0.4, complianceMod));
                totalCost += fine;
                state.domainState.totalFines += fine;
                eventText = t('event_r3_fine').replace('{fine}', '$' + fine.toLocaleString());
            } else if (period === 2) {
                // Regulatory inquiry risk-based
                if (state.domainState.regulatoryRisk > 70) {
                    var inquiry = 250000;
                    totalCost += inquiry;
                    state.domainState.totalFines += inquiry;
                    eventText = t('event_r2_inquiry').replace('{fine}', '$' + inquiry.toLocaleString());
                } else {
                    eventText = t('event_r2_ok');
                }
            } else if (period === 4) {
                if (state.domainState.complianceScore < 40) {
                    var churn = 180000;
                    totalCost += churn;
                    eventText = t('event_r4_churn').replace('{fine}', '$' + churn.toLocaleString());
                } else {
                    eventText = t('event_r4_ok');
                }
            } else if (period === 5) {
                eventText = t('event_r5_expansion');
                if (state.domainState.complianceScore > 70 && state.domainState.privacyCulture > 60) {
                    dTrust += 8;
                    dCompliance += 5;
                } else {
                    dRisk += 10;
                    dTrust -= 5;
                }
            } else {
                eventText = t('event_r1_ok');
            }

            // Apply changes
            state.domainState.budget -= totalCost;
            state.domainState.complianceScore = Math.max(0, Math.min(100, state.domainState.complianceScore + dCompliance));
            state.domainState.customerTrust = Math.max(0, Math.min(100, state.domainState.customerTrust + dTrust));
            state.domainState.privacyCulture = Math.max(0, Math.min(100, state.domainState.privacyCulture + dCulture));
            state.domainState.regulatoryRisk = Math.max(0, Math.min(100, state.domainState.regulatoryRisk + dRisk));

            state.domainState.complianceHistory.push(state.domainState.complianceScore);
            state.domainState.trustHistory.push(state.domainState.customerTrust);
            state.domainState.cultureHistory.push(state.domainState.privacyCulture);
            state.domainState.riskHistory.push(state.domainState.regulatoryRisk);
            state.domainState.budgetHistory.push(Math.max(0, state.domainState.budget));

            // Build event log entry
            var prefix = '<div class="ds-log-entry"><strong>' + t('period_label') + ' ' + period + ':</strong> ';
            var deltaLine = t('log_deltas')
                .replace('{c}', (dCompliance >= 0 ? '+' : '') + dCompliance)
                .replace('{t}', (dTrust >= 0 ? '+' : '') + dTrust)
                .replace('{p}', (dCulture >= 0 ? '+' : '') + dCulture)
                .replace('{r}', (dRisk >= 0 ? '+' : '') + dRisk);
            var costLine = t('log_cost').replace('{cost}', '$' + totalCost.toLocaleString());
            var overLine = '';
            if (state.domainState.budget < 0) {
                overLine = '<br><span class="ds-log-neutral">' + t('event_over_budget').replace('{over}', '$' + Math.abs(Math.round(state.domainState.budget)).toLocaleString()) + '</span>';
            }
            var entry = prefix + eventText + '<br><span class="ds-log-neutral">' + deltaLine + '</span><br><span class="ds-log-neutral">' + costLine + '</span>' + overLine + '</div>';
            state.domainState.eventLog = entry + state.domainState.eventLog;

            var logEl = document.getElementById('eventLogText');
            if (logEl) logEl.innerHTML = state.domainState.eventLog;

            var self = this;
            setTimeout(function() { self._updateBriefing({ currentPeriod: period + 1 }); self._updateBars(state); }, 450);

            return {
                period: period,
                dCompliance: dCompliance,
                dTrust: dTrust,
                dCulture: dCulture,
                dRisk: dRisk,
                cost: totalCost,
                fine: fine,
                compliance: state.domainState.complianceScore,
                trust: state.domainState.customerTrust,
                culture: state.domainState.privacyCulture,
                risk: state.domainState.regulatoryRisk,
                budget: state.domainState.budget
            };
        }

        _updateBars(state) {
            var pairs = [
                ['complianceBar', state.domainState.complianceScore],
                ['trustBar', state.domainState.customerTrust],
                ['cultureBar', state.domainState.privacyCulture],
                ['riskBar', state.domainState.regulatoryRisk]
            ];
            for (var i = 0; i < pairs.length; i++) {
                var el = document.getElementById(pairs[i][0]);
                if (el) el.style.width = pairs[i][1] + '%';
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.budget',
                (v) => '$' + Math.max(0, Math.round(v)).toLocaleString());
            uiManager.bind('complianceDisplay', 'domainState.complianceScore',
                (v) => Math.round(v));
            uiManager.bind('trustDisplay', 'domainState.customerTrust',
                (v) => Math.round(v));
            uiManager.bind('cultureDisplay', 'domainState.privacyCulture',
                (v) => Math.round(v));
            uiManager.bind('riskDisplay', 'domainState.regulatoryRisk',
                (v) => Math.round(v));

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
                self._updateBars(window.mySimulation.state);
                var logEl = document.getElementById('eventLogText');
                if (logEl && window.mySimulation.state.domainState.eventLog) {
                    logEl.innerHTML = window.mySimulation.state.domainState.eventLog;
                }
            }, 200);

            // v1.1.0 FIX: the host rewinds state on Undo but does not re-render the
            // sim-owned DOM. Re-sync briefing, KPI bars and the event log after an undo.
            var undoBtn = document.getElementById('undoBtn');
            if (undoBtn && !undoBtn._dsUndoBound) {
                undoBtn._dsUndoBound = true;
                undoBtn.addEventListener('click', function() {
                    setTimeout(function() {
                        var st = window.mySimulation.state;
                        self._updateBriefing(st);
                        self._updateBars(st);
                        var logEl = document.getElementById('eventLogText');
                        if (logEl) logEl.innerHTML = (st.domainState && st.domainState.eventLog) || '';
                    }, 60);
                });
            }
        }

