        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1].results || {};
            var compliance = last.compliance || 0;
            var trust = last.trust || 0;
            var culture = last.culture || 0;
            var risk = last.risk || 0;
            var budget = last.budget || 0;
            var fines = history.reduce((s, r) => s + ((r.results && r.results.fine) || 0), 0);

            // Weighted score per rubric
            var complianceWeight = compliance * 0.30;
            var engineeringWeight = ((compliance + culture) / 2) * 0.25;
            var governanceWeight = culture * 0.25;
            var crisisWeight = trust * 0.20;
            var riskPenalty = risk * 0.15;
            var finalScore = Math.round(complianceWeight + engineeringWeight + governanceWeight + crisisWeight - riskPenalty);

            var performance = 'Developing';
            if (finalScore > 55 && compliance > 65 && trust > 60) performance = 'Proficient';
            if (finalScore > 70 && compliance > 75 && trust > 70 && culture > 60) performance = 'Exemplary';

            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
            var insights = [];
            if (compliance >= 75) insights.push(t('ins_comp_strong'));
            else if (compliance < 50) insights.push(t('ins_comp_weak'));
            if (trust >= 75) insights.push(t('ins_trust_strong'));
            else if (trust < 50) insights.push(t('ins_trust_weak'));
            if (culture >= 65) insights.push(t('ins_culture_strong'));
            else if (culture < 40) insights.push(t('ins_culture_weak'));
            if (risk >= 70) insights.push(t('ins_risk_high'));
            if (fines > 0) insights.push(t('ins_fines').replace('{fines}', '$' + fines.toLocaleString()));
            if (budget < 500000) insights.push(t('ins_budget_low'));

            return {
                finalScore: finalScore,
                compliance: compliance,
                trust: trust,
                culture: culture,
                risk: risk,
                budget: budget,
                totalFines: fines,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.risk > 75) return window.mySimulation.t('hint_high_risk');
            if (results.trust < 45) return window.mySimulation.t('hint_low_trust');
            if (results.compliance < 40) return window.mySimulation.t('hint_low_compliance');
            if (state.domainState.budget < 1000000) return window.mySimulation.t('hint_low_budget');
            if (results.culture > 70 && results.compliance > 70) return window.mySimulation.t('hint_strong');
            return null;
        }

